<?php declare(strict_types=1);namespace StudPulse\Domain;use StudPulse\Database\DB;use StudPulse\Integrations\WebPush;final class Notices{private static array$published=[];public static function group(array$membership,string$type,string$title,string$target,string$id,int$revision=1):void{$preference=$type==='announcement'?'announcements':'homework';$key=$target.':'.$id.':'.$revision;if(DB::run("INSERT IGNORE INTO notifications(id,recipient_user_id,type,title,body,related_type,related_id,dedupe_key) SELECT UUID(),m.user_id,?,?,?, ?,?,? FROM group_memberships m LEFT JOIN user_preferences p ON p.user_id=m.user_id WHERE m.group_id=? AND m.term_id=? AND m.valid_from<=UTC_TIMESTAMP(6) AND m.valid_to>UTC_TIMESTAMP(6) AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(p.preferences,'$.notifications.$preference')),'true')='true' GROUP BY m.user_id",[$type,$title,'Откройте StudPulse, чтобы посмотреть подробности.',$target,$id,$key,$membership['group_id'],$membership['term_id']])->rowCount()){self::$published[]=$key;}}public static function deliverPublished():void{foreach(self::$published as$key){WebPush::deliverPending($key);}}}